sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float phase;
uniform float repeat;
uniform float alpha;
uniform float squeeze;
uniform float saturation;
layout(color) uniform half4 redColor;
layout(color) uniform half4 greenColor;
layout(color) uniform half4 blueColor;
uniform float reverse;
uniform float scaleBrightness;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    float3 base = float3(c.rgb) / float(c.a);
    float x = (reverse > 0.5 ? 1.0 - luma(base) : luma(base)) * repeat + phase;
    float3 d = abs(fract(float3(x, x - 1.0 / 3.0, x - 2.0 / 3.0) + 0.5) - 0.5);
    float3 k = clamp(5.0 / 3.0 + 0.235 * squeeze - 4.0 * d, 0.0, 1.0);
    float4 g = k.x * float4(redColor) + k.y * float4(greenColor) + k.z * float4(blueColor);
    g.a = min(g.a, 1.0);
    float3 mapped = scaleBrightness > 0.5 ? g.rgb * luma(base) : g.rgb;
    float grey = luma(mapped);
    mapped = grey + (mapped - grey) * (0.5 + 0.5 * clamp(2.0 * saturation + 1.0, 0.0, 2.0));
    float3 rgb = mix(base, mapped, clamp(alpha, 0.0, 1.0) * g.a);
    return half4(half3(clamp(rgb, 0.0, 1.0)) * c.a, c.a);
}
